<?php
$MK_CFG  = require __DIR__ . '/teams.config.php';   // Team-Kürzel, Farben, Abo, Tabellen, Typen
$logoB64 = "";
// Für das JS: keine URLs, nur was die Anzeige braucht
$jsCfg = [
    'teams' => array_map(fn($t) => [
        'farbe'   => $t['farbe'],
        'abo'     => !empty($t['abo']),
        'fd_name' => $t['fd_name'] ?? '',
        'tabelle' => !empty($t['tabelle']),
    ], $MK_CFG['teams']),
    'farbe_sonst' => $MK_CFG['farbe_sonst'] ?? '#6d4c41',
    'typen'       => $MK_CFG['typen'],
];
// Link-Vorschau beim Teilen eines Spieltags (?md=…): Titel/Beschreibung aus matchdays.json
$ogTitle = 'MaTo Kicker – Live';
$ogDesc  = 'Live-Ergebnisse, Torschützen und Spielplan';
$ogMd    = preg_replace('/[^a-zA-Z0-9_\-]/', '', (string)($_GET['md'] ?? ''));
if ($ogMd !== '' && is_file(__DIR__ . '/data/matchdays.json')) {
    $mdsOg = json_decode((string)@file_get_contents(__DIR__ . '/data/matchdays.json'), true);
    $tmsOg = json_decode((string)@file_get_contents(__DIR__ . '/data/teams.json'), true) ?: [];
    if (is_array($mdsOg)) foreach ($mdsOg as $m) {
        if (($m['id'] ?? '') !== $ogMd) continue;
        $d = explode('-', substr(str_replace('/', '-', (string)($m['date'] ?? '')), 0, 10));
        $dTxt = count($d) === 3 ? sprintf('%02d.%02d.%s', $d[2], $d[1], $d[0]) : '';
        // MaTo-Teams als Kürzel (Haupt-Team zuerst) + Typ
        $keys = [];
        $ids  = array_values(array_unique(array_filter(array_merge([$m['home_team_id'] ?? ''], $m['team_ids'] ?? []))));
        foreach ($ids as $id) foreach ($tmsOg as $t) {
            if (($t['id'] ?? '') !== $id || empty($t['is_home'])) continue;
            if (preg_match('/\(([^)]+)\)\s*$/', (string)$t['name'], $mm) && isset($MK_CFG['teams'][trim($mm[1])])) $keys[] = trim($mm[1]);
        }
        $typ = $MK_CFG['typen'][$m['type'] ?? ''] ?? '';
        $ogTitle = 'MaTo ' . ($keys ? implode('/', $keys) : 'Kicker') . ' – ' . ($typ !== '' ? $typ . ': ' : '') . ($m['event'] ?? 'Spieltag');
        $ogDesc  = trim($dTxt . ' · Live-Ergebnisse und Torschützen', ' ·');
        break;
    }
}
$ogScheme = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';
$ogBase   = $ogScheme . '://' . ($_SERVER['HTTP_HOST'] ?? 'localhost') . rtrim(dirname($_SERVER['SCRIPT_NAME'] ?? '/'), '/\\') . '/';
?>
