  .cbtn{border:1px solid var(--border);border-radius:6px;padding:4px 9px;font-size:.72rem;font-weight:600;
        text-decoration:none;cursor:pointer;line-height:1;display:inline-flex;align-items:center;
        justify-content:center;white-space:nowrap}
  .cbtn-g{background:#fff;color:#1a73e8;border-color:#1a73e8} .cbtn-g:hover{background:#e8f0fe}
  .cbtn-i{background:#fff;color:var(--red);border-color:var(--red)} .cbtn-i:hover{background:var(--red-p)}
  @media(max-width:520px){.mdl-date{min-width:80px;font-size:.8rem}.mdl-ev{font-size:.8rem}
    .cbtn{padding:4px 7px;font-size:.68rem}}

  /* Kopf-Link (Logo + Titel gemeinsam anklickbar) */
  .hdr-home{display:flex;align-items:center;gap:10px;text-decoration:none;color:inherit;cursor:pointer}
  .hdr-home:hover h1{text-decoration:underline;text-underline-offset:3px}

  /* Kalender-Navigation (3 Monate vor/zurück) */
  .cal-nav{display:flex;align-items:center;justify-content:center;gap:12px;margin-bottom:10px}
  .cal-nav-btn{background:var(--red);color:#fff;border:none;width:30px;height:30px;border-radius:50%;
               font-size:1.15rem;line-height:1;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:.15s}
  .cal-nav-btn:hover{background:var(--red-l)}
  .cal-nav-lbl{background:none;border:none;color:var(--red);font-weight:600;font-size:.86rem;
               cursor:pointer;padding:5px 10px;border-radius:6px;min-width:150px;text-align:center}
  .cal-nav-lbl:hover{background:var(--red-p)}
</style>
</head>
