<script>
const API='api.php',REFRESH=60,POLL=20;  // POLL = schnelle Änderungsprüfung (Sek.), REFRESH = erzwungene Komplettaktualisierung (Sek.)
const MK_CFG=<?= json_encode($jsCfg, JSON_UNESCAPED_UNICODE) ?>;
const MK_KEYS=Object.keys(MK_CFG.teams);
let allTeams=[],allPlayers=[],allMatchdays=[],curResults=[];
let curMdId='',lastTs=0,autoOn=false;
let rfTimer=null,pgTimer=null,pgVal=0,tickCount=0;
const liveTimers={};

function getMdUrl(){return new URLSearchParams(location.search).get('md')||'';}
function setMdUrl(id){const u=new URL(location.href);id?u.searchParams.set('md',id):u.searchParams.delete('md');history.replaceState(null,'',u);}
async function get(a){return (await fetch(`${API}?action=${a}`)).json();}

function elapsed(r,halfSec){
  if(!r.started_at)return null;
  const now=Math.floor(Date.now()/1000);
  const half=r.current_half||1;
  const st=r.status||'not_started';
  if(half>=3){
    // Verlängerung: startet bei 2× Halbzeitlänge; vor dem Anpfiff eingefroren
    const base=2*(halfSec||1800);
    if(!r.et_start_at)return base;
    return base+Math.max(0,(r.et_end_at||r.ended_at||now)-r.et_start_at);
  }
  if(half>=2){
    const base=halfSec||1800;
    const s2=r.second_half_start_at||now;
    return base+Math.max(0,(r.half2_end_at||r.ended_at||now)-s2);
  }
  if(st==='halftime')return Math.max(0,(r.half1_end_at||now)-r.started_at);
  return Math.max(0,(r.ended_at||now)-r.started_at);
}
// ── Pokal-Helfer: Halbzeitstand, Elfmeterschießen, Live-Status ──
function isGuestScorer(s){return s==='__gast__'||String(s||'').startsWith('guest:');}
// Torminute als Text, Nachspielzeit als „30+2'"; leer bei Altdaten ohne Minute
function goalMinTxt(info,halfMin){
  if(!info||info.minute==null||info.minute==='')return '';
  const m=+info.minute,h=+halfMin||30;
  if(info.phase===1&&m>h)return `${h}+${m-h}'`;
  if(info.phase===2&&m>2*h)return `${2*h}+${m-2*h}'`;
  return `${m}'`;
}
// Halbzeitstand aus den Tor-Phasen; null, wenn Altdaten ohne Phase vorhanden sind
function htScore(r){
  const sc=r.scorers||[],info=r.scorer_info||[];let h=0,g=0;
  for(let i=0;i<sc.length;i++){const f=info[i];if(!f||!f.phase)return null;if(f.phase===1){isGuestScorer(sc[i])?g++:h++;}}
  return {h,g};
}
function penScore(r){let h=0,g=0;(r.pen_shots||[]).forEach(p=>{if(p.scored){p.team==='guest'?g++:h++;}});return {h,g};}
function hasPens(r){return (r.status==='penalties')||((r.pen_shots||[]).length>0);}
function isLive(r){return r.status==='running'||(r.status==='extra_time'&&!!r.et_start_at);}
function isActive(r){return ['running','extra_time','penalties'].includes(r.status);}
function fmt(s){const m=Math.floor(s/60),sec=s%60;return String(m).padStart(2,'0')+':'+String(sec).padStart(2,'0');}
function toMin(t){if(!t||!t.includes(':'))return null;const[h,m]=t.split(':').map(Number);return h*60+m;}
function pad2(n){return String(n).padStart(2,'0');}

// Datum immer mit führenden Nullen (TT.MM.JJJJ)
function normDate(d){return d?String(d).replace(/\//g,'-').substring(0,10):'';}
function fmtDate(d){const p=normDate(d).split('-');if(p.length<3)return d;return pad2(p[2])+'.'+pad2(p[1])+'.'+p[0];}
function escH(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

/* ── MaTo-Teams, Typen, Farben (teams.config.php) ────────────────────── */
// Kürzel aus dem Namen („MaTo Kicker (D1)“ → „D1“), nur wenn in teams.config.php definiert
function teamKey(t){const m=String(t&&t.name||'').match(/\(([^)]+)\)\s*$/);const k=m?m[1].trim():'';return MK_CFG.teams[k]?k:null;}
function teamColor(t){const k=teamKey(t);return k?MK_CFG.teams[k].farbe:MK_CFG.farbe_sonst;}
function typeLabel(k){return MK_CFG.typen[k]||'';}
// MaTo-Teams eines Spieltags: Haupt-Team zuerst, dann weitere angehakte.
// Altes Team ohne Kürzel („MaTo Kicker“) nur, wenn kein konfiguriertes Team (D1/D2/C1) dabei ist.
function mdHomeTeams(md){
  const ids=[md.home_team_id,...(md.team_ids||[])].filter((v,i,a)=>v&&a.indexOf(v)===i);
  const all=ids.map(id=>allTeams.find(t=>t.id===id&&t.is_home)).filter(Boolean);
  const cfg=all.filter(t=>teamKey(t));
  return cfg.length?cfg:all;
}
function mdKeys(md){return mdHomeTeams(md).map(teamKey).filter(Boolean);}
function mdColors(md){const c=mdHomeTeams(md).map(teamColor);return c.length?c:[MK_CFG.farbe_sonst];}
// Textlabel (Dropdowns): „D1 · Spieltag · Freitext“
function mdLabel(md){
  const k=mdKeys(md),ty=typeLabel(md.type);
  return [k.join('/'),ty,md.event].filter(Boolean).join(' · ');
}
// Kalender-/Teilen-Titel: „MaTo D1 – Spieltag: Freitext“ (gleich wie calendar.php)
function mdCalTitle(md){
  const k=mdKeys(md),ty=typeLabel(md.type);
  return 'MaTo '+(k.length?k.join('/'):'Kicker')+' – '+(ty?ty+': ':'')+md.event;
}
function mdBadgesHtml(md){
  const b=mdHomeTeams(md).map(t=>`<span class="tm-badge" style="background:${teamColor(t)}">${escH(teamKey(t)||'MaTo')}</span>`).join('');
  const ty=typeLabel(md.type);
  return b+(ty?`<span class="ty-lbl">${escH(ty)}</span>`:'');
}
// Hintergrund für Kalendertage: eine Farbe oder geteilt bei mehreren Teams
function colorBg(cols){
  const u=[...new Set(cols)];
  if(u.length<2)return u[0];
  const step=100/u.length;
  return 'linear-gradient(135deg,'+u.map((c,i)=>`${c} ${i*step}%,${c} ${(i+1)*step}%`).join(',')+')';
}
// Gespielte Tage: Teamfarbe stark mit Hellgrau gemischt (hellrotgrau, hellblaugrau …)
function mixHex(c,base,t){
  const p=h=>{h=h.replace('#','');if(h.length===3)h=h.split('').map(x=>x+x).join('');return [0,2,4].map(i=>parseInt(h.substr(i,2),16));};
  const a=p(c),b=p(base);
  return '#'+a.map((v,i)=>Math.round(v*t+b[i]*(1-t)).toString(16).padStart(2,'0')).join('');
}
function pastColor(c){return mixHex(c,'#e3e7ea',.28);}
function pastText(c){return mixHex(c,'#546e7a',.45);}
function aboKeys(){return MK_KEYS.filter(k=>MK_CFG.teams[k].abo);}

/* ── Übersicht: Mini-Kalender der kommenden 3 Monate ─────────────────── */
const MONTHS_DE=['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'];
const MONTHS_SH=['Jan','Feb','Mär','Apr','Mai','Jun','Jul','Aug','Sep','Okt','Nov','Dez'];
const WD_DE=['Mo','Di','Mi','Do','Fr','Sa','So'];
let calOffset=0; // Verschiebung in Monaten (0 = aktueller Monat)
function ymdKey(y,m,d){return y+'-'+pad2(m+1)+'-'+pad2(d);}

function renderOverview(){
  renderCalendars();
  renderLegend();
  renderMdList();
  updateOverviewVisibility();
}

function renderLegend(){
  const el=document.getElementById('calLegend');if(!el)return;
  let h=MK_KEYS.map(k=>`<span><i style="background:${MK_CFG.teams[k].farbe}"></i>${escH(k)}</span>`).join('');
  // Farbe „sonstige“ nur zeigen, wenn es Termine ohne konfiguriertes Team gibt (altes Team „MaTo Kicker“)
  if(allMatchdays.some(md=>!mdKeys(md).length))h+=`<span><i style="background:${MK_CFG.farbe_sonst}"></i>MaTo (alt)</span>`;
  el.innerHTML=h+`<span><i style="background:${colorBg(MK_KEYS.map(k=>pastColor(MK_CFG.teams[k].farbe)))}"></i>bereits gespielt</span>`;
}

function shiftCal(delta){
  calOffset = delta===0 ? 0 : calOffset+delta;
  renderCalendars();
}

function renderCalendars(){
  const cal=document.getElementById('calWrap');
  if(!cal)return;
  const today=new Date(); today.setHours(0,0,0,0);
  const byDate={};
  allMatchdays.forEach(md=>{const nd=normDate(md.date);(byDate[nd]=byDate[nd]||[]).push(md);});
  cal.innerHTML='';
  const base=new Date(today.getFullYear(),today.getMonth()+calOffset,1);
  for(let i=0;i<3;i++){
    const dt=new Date(base.getFullYear(),base.getMonth()+i,1);
    cal.appendChild(buildMonth(dt.getFullYear(),dt.getMonth(),byDate,today));
  }
  // Beschriftung des Zeitraums
  const last=new Date(base.getFullYear(),base.getMonth()+2,1);
  const lbl=document.getElementById('calNavLbl');
  if(lbl){
    const range = base.getFullYear()===last.getFullYear()
      ? MONTHS_SH[base.getMonth()]+' – '+MONTHS_SH[last.getMonth()]+' '+last.getFullYear()
      : MONTHS_SH[base.getMonth()]+' '+base.getFullYear()+' – '+MONTHS_SH[last.getMonth()]+' '+last.getFullYear();
    lbl.textContent = calOffset!==0 ? range+' ⟲' : range;
  }
}

function buildMonth(year,month,byDate,today){
  const box=document.createElement('div');box.className='cal';
  const h=document.createElement('div');h.className='cal-h';
  h.textContent=MONTHS_DE[month]+' '+year;box.appendChild(h);
  const grid=document.createElement('div');grid.className='cal-grid';
  WD_DE.forEach(w=>{const c=document.createElement('div');c.className='cal-wd';c.textContent=w;grid.appendChild(c);});
  const lead=(new Date(year,month,1).getDay()+6)%7; // Montag = 0
  const dim=new Date(year,month+1,0).getDate();
  for(let i=0;i<lead;i++){const c=document.createElement('div');c.className='cal-d empty';grid.appendChild(c);}
  for(let d=1;d<=dim;d++){
    const c=document.createElement('div');c.className='cal-d';c.textContent=d;
    const cur=new Date(year,month,d);
    if(cur.getTime()===today.getTime())c.classList.add('today');
    const mds=byDate[ymdKey(year,month,d)];
    if(mds){
      const upcoming=cur>=today;
      c.classList.add(upcoming?'has-up':'has-past');
      const cols=mds.flatMap(mdColors);
      if(upcoming)c.style.background=colorBg(cols);
      else{c.style.background=colorBg(cols.map(pastColor));c.style.color=pastText(cols[0]);}
      c.title=mds.map(mdLabel).join(' | ');
      c.onclick=()=>jumpToMd(mds[0].id,upcoming);
    }
    grid.appendChild(c);
  }
  box.appendChild(grid);
  return box;
}

function jumpToMd(id,upcoming){
  if(upcoming){switchTab('current');document.getElementById('mdSel').value=id;selectMd();}
  else        {switchTab('archive');document.getElementById('mdSelArchive').value=id;selectMdArchive();}
  window.scrollTo({top:0,behavior:'smooth'});
}

/* ── Liste der kommenden Spieltage + Kalender öffnen ─────────────────── */
function upcomingMds(){
  return allMatchdays.filter(m=>isUpcomingOrToday(m.date))
    .sort((a,b)=>normDate(a.date).localeCompare(normDate(b.date)));
}
// Effektive Startzeit eines Spieltags: bevorzugt das Feld md.time, sonst aus dem Eventnamen.
function mdTime(md){
  if(md && md.time && /^\d{1,2}:\d{2}$/.test(md.time)){const p=md.time.split(':');return pad2(p[0])+':'+p[1];}
  const m=((md&&md.event)||'').match(/(\d{1,2}):(\d{2})/);
  return m?pad2(m[1])+':'+m[2]:'';
}
function renderMdList(){
  const wrap=document.getElementById('mdListWrap');if(!wrap)return;
  const up=upcomingMds();
  if(!up.length){wrap.innerHTML='';return;}
  const ak=aboKeys();
  const aboTxt=ak.length?ak.join('/'):'';
  let html='<div class="mdl-head"><span class="mdl-title">Kommende Spieltage</span>'
    +'<span class="mdl-actions"><span class="mdl-actions-lbl">Kalender-Import'+(aboTxt?' '+escH(aboTxt):'')+':</span>'
    +'<a class="hb hb-g" target="_blank" rel="noopener" href="'+gcalSubscribeUrl()+'" title="Am Computer: '+escH(aboTxt||'alle')+'-Spieltage im Google Kalender abonnieren (aktualisiert sich automatisch)">💻 PC</a>'
    +'<a class="hb hb-ap" href="'+webcalSubscribeUrl()+'" title="Am Handy (iPhone & Android): '+escH(aboTxt||'alle')+'-Spieltage direkt in der Kalender-App abonnieren">📱 iPhone</a>'
    +'<a class="hb hb-ics" href="calendar.php?dl=1" title="Alle kommenden '+escH(aboTxt)+'-Spieltage als ICS-Datei herunterladen">📅 ICS</a>'
    +'</span></div>'
    +'<p class="mdl-hint">Hinweis: Für die <b>automatische Kalenderaktualisierung</b> im Google Kalender muss der Kalender einmalig am Computer über den "PC"-Button im Browser hinzugefügt werden. Für einen einmaligen Import <b>ohne automatische Aktualisierung</b> einfach den "ICS"-Button verwenden.'
    +(aboTxt?' Abo und ICS-Datei enthalten nur die <b>'+escH(aboTxt)+'-Spiele</b>; andere Termine einzeln über „Google“/„ICS“ in der Liste eintragen.':'')+'</p>'
    +'<ul class="mdl">';
  up.forEach(md=>{
    const t=mdTime(md);
    const jump="jumpToMd('"+md.id+"',true)";
    html+='<li style="--c:'+mdColors(md)[0]+'"><span class="mdl-main" role="button" tabindex="0" title="Zum Spieltag springen"'
      +' onclick="'+jump+'"'
      +' onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();'+jump+'}">'
      +'<span class="mdl-date">'+fmtDate(md.date)
      +(t?'<span class="mdl-time">🕐 '+t+'</span>':'')+'</span>'
      +'<span class="mdl-ev"><span class="mdl-tags">'+mdBadgesHtml(md)+'</span>'+escH(md.event)+'</span>'
      +'</span>'
      +'<span class="mdl-btns">'
      +'<a class="cbtn cbtn-g" target="_blank" rel="noopener" href="'+gcalUrl(md)+'" title="In Google Kalender eintragen">Google</a>'
      +'<a class="cbtn cbtn-i" target="_blank" rel="noopener" href="calendar.php?id='+encodeURIComponent(md.id)+'&dl=1" title="Als ICS-Datei herunterladen">ICS</a>'
      +'</span></li>';
  });
  wrap.innerHTML=html+'</ul>';
}

// Verzeichnis der App (für absolute Feed-URL)
function baseDir(){return location.pathname.replace(/[^/]*$/,'');}

// Kalender-Abo (Google, am PC ideal): öffnet im Browser Googles „Kalender
// hinzufügen"-Dialog und legt ein echtes, automatisch aktualisiertes Abo an.
// Die webcal://-Feed-URL im cid ist die Form, die auf dem Desktop zuverlässig
// den Import-Dialog auslöst.
function gcalSubscribeUrl(){
  return 'https://calendar.google.com/calendar/render?cid=webcal://'+location.host+baseDir()+'calendar.php';
}
// iPhone-Abo: blanker webcal://-Link. Auf dem iPhone öffnet iOS damit direkt den
// nativen „Abonnieren"-Dialog des Apple-Kalenders (am Desktop dagegen unzuverlässig).
function webcalSubscribeUrl(){
  return 'webcal://'+location.host+baseDir()+'calendar.php';
}

// Direkt-Link, der Google Kalender mit vorausgefülltem Termin öffnet (kein Download).
// Terminbeginn 45 Min vor der angegebenen Uhrzeit, Dauer 3 Stunden.
function gcalUrl(md){
  const p=normDate(md.date).split('-'); if(p.length<3)return'#';
  const y=p[0],mo=pad2(p[1]),da=pad2(p[2]);
  const t=mdTime(md); // "HH:MM" aus Feld md.time (bevorzugt) oder Eventname
  let dates,ctz='';
  if(t){
    const hh=+t.split(':')[0], mi=+t.split(':')[1];
    const start=new Date(+p[0],+p[1]-1,+p[2],hh,mi,0);
    start.setMinutes(start.getMinutes()-45);              // 45 Min früher
    const end=new Date(start.getTime()+3*3600*1000);      // 3 Std. Dauer
    const f=d=>d.getFullYear()+pad2(d.getMonth()+1)+pad2(d.getDate())+'T'+pad2(d.getHours())+pad2(d.getMinutes())+'00';
    dates=f(start)+'/'+f(end);
    ctz='&ctz=Europe/Berlin';
  }else{
    const nx=new Date(+y,+p[1]-1,+p[2]+1);
    const end=nx.getFullYear()+pad2(nx.getMonth()+1)+pad2(nx.getDate());
    dates=y+mo+da+'/'+end; // Ganztags-Termin (keine Uhrzeit)
  }
  const url=location.origin+location.pathname+'?md='+encodeURIComponent(md.id);
  return 'https://calendar.google.com/calendar/render?action=TEMPLATE'
    +'&text='+encodeURIComponent(mdCalTitle(md))
    +'&dates='+dates+ctz
    +'&details='+encodeURIComponent('Live-Ergebnisse: '+url)
    +'&location='+encodeURIComponent('MaTo Kicker Live');
}

function updateOverviewVisibility(){
  const ov=document.getElementById('overview');if(!ov)return;
  const onCurrent=!document.getElementById('tabCurrent').classList.contains('hidden');
  ov.style.display=(onCurrent&&!curMdId)?'block':'none';
}

// Spieler für ein bestimmtes Team (team_id kann String oder Array sein)
function getPlayersForTeam(teamId){
  if(!teamId)return [];
  return allPlayers.filter(p=>{
    if(Array.isArray(p.team_id)) return p.team_id.includes(teamId);
    return p.team_id===teamId;
  });
}
function getDefaultHomeTeam(){return allTeams.find(t=>t.is_home)||null;}

// Heute und Zukunft vs. Archiv
function isUpcomingOrToday(dateStr){
  if(!dateStr)return true;
  // Normalisieren: Schrägstriche -> Bindestriche, nur ersten 10 Zeichen (YYYY-MM-DD)
  const norm=dateStr.replace(/\//g,'-').substring(0,10);
  const parts=norm.split('-');
  if(parts.length<3)return true;
  // Date direkt aus Teilen bauen, kein Timezone-Problem
  const d=new Date(parseInt(parts[0]),parseInt(parts[1])-1,parseInt(parts[2]));
  const today=new Date(); today.setHours(0,0,0,0);
  return d>=today;
}

async function init(){
  [allTeams,allPlayers,allMatchdays]=await Promise.all([get('get_teams'),get('get_players'),get('get_matchdays')]);
  const selMain=document.getElementById('mdSel');
  const selArch=document.getElementById('mdSelArchive');

  function sortAsc(a,b){return normDate(a.date).localeCompare(normDate(b.date));}
  function sortDesc(a,b){return normDate(b.date).localeCompare(normDate(a.date));}

  const upcoming=allMatchdays.filter(m=>isUpcomingOrToday(m.date)).sort(sortAsc);
  const archive =allMatchdays.filter(m=>!isUpcomingOrToday(m.date)).sort(sortDesc);

  upcoming.forEach(md=>{
    const o=document.createElement('option'); o.value=md.id;
    o.textContent=`${fmtDate(md.date)} – ${mdLabel(md)}`;
    selMain.appendChild(o);
  });
  archive.forEach(md=>{
    const o=document.createElement('option'); o.value=md.id;
    o.textContent=`${fmtDate(md.date)} – ${mdLabel(md)}`;
    selArch.appendChild(o);
  });

  // Archiv-Tab ausblenden wenn leer
  if(!archive.length){
    document.getElementById('tabBtnArchive').style.display='none';
  }

  renderOverview();

  const u=getMdUrl();
  if(u){
    if(upcoming.find(m=>m.id===u)){
      selMain.value=u; switchTab('current');
    } else {
      selArch.value=u; switchTab('archive');
    }
    await selectMd(false, u);
  }
}

function switchTab(tab){
  document.getElementById('tabBtnCurrent').classList.toggle('active', tab==='current');
  document.getElementById('tabBtnTable').classList.toggle('active', tab==='table');
  document.getElementById('tabBtnArchive').classList.toggle('active', tab==='archive');
  document.getElementById('tabCurrent').classList.toggle('hidden', tab!=='current');
  document.getElementById('tabTable').classList.toggle('hidden', tab!=='table');
  document.getElementById('tabArchive').classList.toggle('hidden', tab!=='archive');
  // Auswahl der jeweils anderen Dropdowns zurücksetzen
  if(tab!=='current') document.getElementById('mdSel').value='';
  if(tab!=='archive') document.getElementById('mdSelArchive').value='';
  lastTs=0; curMdId='';
  // Auf dem Tabellen-Reiter keine Spiele-Liste anzeigen
  document.getElementById('matchList').innerHTML = (tab==='table') ? '' : '<div class="empty">Bitte einen Spieltag auswählen.</div>';
  document.getElementById('updLbl').textContent='';
  stopAuto();
  updateOverviewVisibility();
  if(tab==='table') loadTable();
}

// Ligatabelle je MaTo-Team (table.php?team=…, Cache data/tabelle_<team>.json)
const TABLE_KEYS=MK_KEYS.filter(k=>MK_CFG.teams[k].tabelle);
let curTableTeam=TABLE_KEYS[0]||'';
function renderTableSwitch(){
  const el=document.getElementById('tableSwitch');
  if(TABLE_KEYS.length<2){el.style.display='none';return;}
  el.innerHTML=TABLE_KEYS.map(k=>`<button type="button" class="tbl-sw-btn${k===curTableTeam?' active':''}" style="--c:${MK_CFG.teams[k].farbe}" onclick="loadTable('${k}')">${escH(k)}</button>`).join('');
}
async function loadTable(team){
  if(team)curTableTeam=team;
  renderTableSwitch();
  const wrap=document.getElementById('tableWrap');
  const upd=document.getElementById('tableUpd');
  document.getElementById('tableTitle').textContent='Tabelle'+(curTableTeam?' '+curTableTeam:'');
  wrap.innerHTML='<div class="empty">Tabelle wird geladen…</div>'; upd.textContent='';
  const reqTeam=curTableTeam;
  let data;
  try{
    const res=await fetch('table.php?team='+encodeURIComponent(reqTeam)+'&_='+Date.now(),{cache:'no-store'});
    if(!res.ok) throw new Error('http '+res.status);
    data=await res.json();
  }catch(e){
    if(reqTeam===curTableTeam)wrap.innerHTML='<div class="empty">Tabelle ist zurzeit nicht verfügbar.</div>';
    return;
  }
  if(reqTeam!==curTableTeam)return; // inzwischen auf ein anderes Team umgeschaltet
  const rows=(data&&Array.isArray(data.table))?data.table:[];
  if(!rows.length){ wrap.innerHTML='<div class="empty">Noch keine Tabellendaten vorhanden.</div>'; return; }
  const cfgT=MK_CFG.teams[curTableTeam]||{};
  const homeName=String(cfgT.fd_name||'MaTo Kicker').trim().toLowerCase();
  let html='<div class="ltable-scroll"><table class="ltable"><thead><tr>'
    +'<th>#</th><th class="tl">Mannschaft</th><th>Sp</th><th>S</th><th>U</th><th>N</th><th>Tore</th><th>Diff</th><th>Pkt</th>'
    +'</tr></thead><tbody>';
  rows.forEach(r=>{
    const isHome=String(r.mannschaft||'').trim().toLowerCase()===homeName;
    const td=(r.tordifferenz??0);
    const diff=(td>0?'+':'')+td;
    const tore=r.torverhaeltnis||((r.tore??0)+':'+(r.gegentore??0));
    html+=`<tr class="${isHome?'me':''}">`
      +`<td>${r.platz??''}</td>`
      +`<td class="tl">${escH(r.mannschaft||'')}</td>`
      +`<td>${r.spiele??0}</td>`
      +`<td>${r.gewonnen??0}</td>`
      +`<td>${r.unentschieden??0}</td>`
      +`<td>${r.verloren??0}</td>`
      +`<td class="nowrap">${escH(tore)}</td>`
      +`<td>${diff}</td>`
      +`<td class="pkt">${r.punkte??0}</td>`
      +`</tr>`;
  });
  html+='</tbody></table></div>';
  wrap.innerHTML=html;
  if(data.updated_at){
    const d=new Date(data.updated_at);
    if(!isNaN(d.getTime())) upd.textContent='Stand: '+d.toLocaleString('de-DE',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})+' Uhr';
  }
}

async function selectMdArchive(){
