// ── Wake-Lock: hält den Bildschirm an, solange Auto-Refresh aktiv ist ──
let wakeLock=null;
function setWlIndicator(on){
  const el=document.getElementById('wlIco');
  if(el)el.textContent=on?'· 🔒 Bildschirm bleibt an':'';
}
async function requestWakeLock(){
  if(!('wakeLock' in navigator))return;      // Browser ohne Unterstützung: still ignorieren
  try{
    wakeLock=await navigator.wakeLock.request('screen');
    wakeLock.addEventListener('release',()=>setWlIndicator(false));
    setWlIndicator(true);
  }catch(e){ setWlIndicator(false); }         // z. B. Energiesparmodus lehnt ab
}
async function releaseWakeLock(){
  try{ if(wakeLock) await wakeLock.release(); }catch(e){}
  wakeLock=null; setWlIndicator(false);
}
// Nach Tabwechsel/Sperre wird der Lock automatisch freigegeben – bei Rückkehr neu anfordern
document.addEventListener('visibilitychange',()=>{
  if(document.visibilityState==='visible' && autoOn && curMdId) requestWakeLock();
});

// ── PWA: Service Worker registrieren + Installations-Button ──
if('serviceWorker' in navigator){
  window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js').catch(()=>{}));
}
let deferredPrompt=null;
function isStandalone(){
  return window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone===true;
}
function isIOS(){
  return /iphone|ipad|ipod/i.test(navigator.userAgent) && !window.MSStream;
}
function showInstallBtn(on){
  const b=document.getElementById('installBtn'); if(b)b.style.display=on?'flex':'none';
}
// Android/Chrome: nativen Installationsdialog abfangen und Button einblenden
window.addEventListener('beforeinstallprompt',(e)=>{
  e.preventDefault(); deferredPrompt=e;
  if(!isStandalone()) showInstallBtn(true);
});
window.addEventListener('appinstalled',()=>{ deferredPrompt=null; showInstallBtn(false); });
async function onInstallClick(){
  if(deferredPrompt){
    deferredPrompt.prompt();
    try{ await deferredPrompt.userChoice; }catch(e){}
    deferredPrompt=null; showInstallBtn(false);
  }else if(isIOS()){
    document.getElementById('iosHelp').style.display='flex';   // iPhone: Anleitung zeigen
  }
}
// iPhone kennt kein beforeinstallprompt -> Button mit Anleitung anbieten (falls noch nicht installiert)
if(isIOS() && !isStandalone()) showInstallBtn(true);
function stopAuto(){
  clearInterval(rfTimer);clearInterval(pgTimer);rfTimer=pgTimer=null;
  document.getElementById('progBar').style.display='none';
  releaseWakeLock();
}
function startAuto(){
  stopAuto(); if(!curMdId||!autoOn)return;
  requestWakeLock();
  pgVal=0; tickCount=0; document.getElementById('prog').value=0;
  document.getElementById('progBar').style.display='flex';
  pgTimer=setInterval(()=>{
    pgVal+=100/(POLL*10); if(pgVal>100)pgVal=100;
    document.getElementById('prog').value=pgVal;
    const s=Math.max(0,Math.round(POLL*(1-pgVal/100)));
    document.getElementById('progLbl').textContent=s>0?`Auto – prüft in ${s}s…`:'Aktualisiere…';
  },100);
  // Alle POLL Sekunden auf Änderungen prüfen (leichtgewichtig); nur bei Änderung neu laden.
  // Zusätzlich etwa alle REFRESH Sekunden eine Komplettaktualisierung erzwingen (Sicherheitsnetz).
  const forceEvery=Math.max(1,Math.round(REFRESH/POLL));
  rfTimer=setInterval(async()=>{
    tickCount++;
    await doRefresh(tickCount%forceEvery===0);
    pgVal=0;
  },POLL*1000);
}

async function selectMd(writeUrl=true, forceId=null){
  lastTs=0;
  const id = forceId || document.getElementById('mdSel').value;
  await loadWithId(id, writeUrl);
}

async function loadWithId(id, writeUrl=true){
  curMdId=id;
  if(writeUrl)setMdUrl(curMdId);
  stopAuto(); Object.keys(liveTimers).forEach(k=>{clearInterval(liveTimers[k]);delete liveTimers[k];});
  if(!curMdId){
    document.getElementById('matchList').innerHTML='<div class="empty">Bitte einen Spieltag auswählen.</div>';
    document.getElementById('updLbl').textContent=''; updateOverviewVisibility(); return;
  }
  updateOverviewVisibility();
  await doRefresh(true); if(autoOn)startAuto();
}

async function doRefresh(force=false){
  if(!curMdId)return;
  const ts=(await get(`get_last_update&matchday_id=${curMdId}`)).ts;
  if(!force&&ts===lastTs)return;
  lastTs=ts;
  curResults=await (await fetch(`${API}?action=get_results&matchday_id=${curMdId}`)).json();
  renderMatches();
  // Zeitpunkt der letzten Änderung im Spieltagreporting anzeigen (nicht die aktuelle Uhrzeit)
  const lbl=document.getElementById('updLbl');
  if(ts>0){
    const d=new Date(ts*1000);
    const sameDay=d.toDateString()===new Date().toDateString();
    const t=d.toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'});
    lbl.textContent='Letzte Änderung: '+(sameDay?t+' Uhr':d.toLocaleDateString('de-DE')+', '+t+' Uhr');
  }else{
    lbl.textContent='';
  }
}

function renderMatches(){
  Object.keys(liveTimers).forEach(k=>{clearInterval(liveTimers[k]);delete liveTimers[k];});
  const wrap=document.getElementById('matchList');
  wrap.innerHTML='';

  // Spielplan-Link oberhalb des ersten Spiels (falls beim Spieltag hinterlegt)
  const curMd=allMatchdays.find(m=>m.id===curMdId);
  const acts=document.createElement('div');acts.className='md-actions';
  if(curMd&&curMd.schedule_url){
    const a=document.createElement('a');
    a.className='plan-link';
    a.href=curMd.schedule_url;
    a.target='_blank';
    a.rel='noopener';
    a.innerHTML='📋 Gesamten Spielplan öffnen <span class="ext">↗</span>';
    acts.appendChild(a);
  }
  if(curMd){
    const b=document.createElement('button');b.type='button';b.className='share-btn';
    b.innerHTML='🔗 Spieltag teilen';b.onclick=()=>shareMd(curMd,b);
    acts.appendChild(b);
  }
  if(acts.children.length)wrap.appendChild(acts);

  if(!curResults.length){
    const e=document.createElement('div');e.className='empty';
    e.textContent='Noch keine Begegnungen.';wrap.appendChild(e);
    appendSquads(wrap,curMd);return;
  }

  // Laufende Spiele nach oben sortieren, dann nach kickoff
  // (Spiele bleiben auch sichtbar, wenn das Team inzwischen gelöscht wurde –
  //  der Name kommt dann aus dem eingefrorenen guest_team_name)
  const halfSec=((curMd&&+curMd.half_length)||30)*60;
  const running=curResults.filter(r=>isActive(r));
  const others =curResults.filter(r=>!isActive(r));
  const sorted=[...running,...others];

  sorted.forEach((r,i)=>{
    // Heimteam dieser Begegnung (überschreibbar per home_team_id)
    const defHome=allTeams.find(t=>t.is_home);
    const homeTeamId=r.home_team_id||(defHome?defHome.id:null);
    const home=allTeams.find(t=>t.id===homeTeamId)||defHome;
    const guest=allTeams.find(t=>t.id===r.guest_team_id);
    // Eingefrorene Namen haben Vorrang; Fallback: Live-Lookup in teams.json
    const homeName=r.home_team_name||(home?home.name:'Heim');
    const guestName=r.guest_team_name||(guest?guest.name:'Unbekannt');
    const st=r.status||'not_started';
    const sc=st==='running'?'run':st==='extra_time'?(r.et_start_at?'run':'half'):st==='halftime'?'half':st==='penalties'?'pen':st==='finished'?'fin':'ns';
    const halfTxt=st==='running'?(r.current_half===2?' · 2. HZ':' · 1. HZ'):'';
    const finTxt=hasPens(r)?' · i.E.':((r.current_half||1)>=3?' · n.V.':'');
    const badgeLabel=st==='not_started'?'⏳ Nicht gestartet'
      :st==='running'?('🟢 Läuft'+halfTxt)
      :st==='halftime'?'⏸ Halbzeit'
      :st==='extra_time'?(r.et_start_at?'🟢 Verlängerung':'⏸ Pause vor Verlängerung')
      :st==='penalties'?'🥅 Elfmeterschießen'
      :'🔒 Beendet'+finTxt;
    const ht=(r.started_at&&(r.current_half||1)>=2)?htScore(r):null;
    const ps=hasPens(r)?penScore(r):null;
    const fieldLabel=r.field||'Feld 1';
    const kickoffLabel=r.kickoff?`⏰ ${r.kickoff}`:'';
    const el=elapsed(r,halfSec);
    const timerHtml=(st!=='not_started')&&el!==null
      ?`<span class="timer ${sc}" id="tmr_${r.id}">${fmt(el)}</span>`:'';

    // ── Spielereignisse je Mannschaft: Heim unter dem Heimteam, Gast unter dem Gastteam ──
    // Reihenfolge nach Minute (Spielminuten laufen durch); Einträge ohne Minute (Altdaten) behalten ihre Reihenfolge
    const halfMinV=(halfSec||1800)/60;
    const ev={home:[],guest:[]};
    const evKey=(phase,minute,seq)=>((minute!=null&&minute!=='')?(+minute)*10+(+phase||0):1e6)+seq/1000;
    let seq=0;
    (r.scorers||[]).forEach((s,idx)=>{
      if(!s)return;
      const info=(r.scorer_info||[])[idx]||null;
      const side=isGuestScorer(s)?'guest':'home';
      const nm=s==='__gast__'?'Gast':s.startsWith('guest:')?s.slice(6):s==='Noname'?'Unbekannt':s;
      const gm=goalMinTxt(info,halfMinV);
      const sc=(r.scorer_scores&&r.scorer_scores[idx])?` <span class="ev-sc">(${r.scorer_scores[idx]})</span>`:'';
      const pen=info&&info.pen?'<span class="pen-tag" title="Elfmeter">11m</span>':'';
      ev[side].push({k:evKey(info&&info.phase,info&&info.minute,seq++),
        h:`<div class="ev-item ev-goal">⚽ <b>${escH(nm)}</b>${pen}${gm?` <span class="goal-min">${gm}</span>`:''}${sc}</div>`});
    });
    (r.pen_missed||[]).forEach(pm=>{
      const side=pm.team==='guest'?'guest':'home';
      const nm=(!pm.player||pm.player==='__unbekannt__')?(side==='guest'?'Gast':'Heim'):pm.player;
      const min=(pm.minute!=null&&pm.minute!=='')?` <span class="goal-min">${pm.minute}'</span>`:'';
      ev[side].push({k:evKey(pm.phase,pm.minute,seq++),
        h:`<div class="ev-item"><span class="pen-tag pen-tag-miss">11m ✗</span> ${escH(nm)}${min}</div>`});
    });
    (r.cards||[]).forEach(c=>{
      const side=c.team==='guest'?'guest':'home';
      const sym=(c.type==='red')?'🟥':(c.type==='yellow_red')?'🟨🟥':'🟨';
      const nm=(!c.player||c.player==='__unbekannt__')?(side==='guest'?'Gast':'Heim'):c.player;
      const min=(c.minute!=null&&c.minute!=='')?` <span class="goal-min">${c.minute}'</span>`:'';
      ev[side].push({k:evKey(null,c.minute,seq++),h:`<div class="ev-item">${sym} ${escH(nm)}${min}</div>`});
    });
    const evCol=side=>ev[side].sort((a,b)=>a.k-b.k).map(x=>x.h).join('');
    const eventsHtml=(ev.home.length||ev.guest.length)
      ?`<div class="mc-ev"><div class="ev-col ev-home">${evCol('home')}</div><div class="ev-mid"></div><div class="ev-col ev-guest">${evCol('guest')}</div></div>`:'';

    // Elfmeterschießen ebenfalls je Mannschaft
    const penCol=side=>(r.pen_shots||[]).map((p,i)=>({p,i})).filter(x=>(x.p.team==='guest'?'guest':'home')===side).map(({p,i})=>{
      const nm=(!p.player||p.player==='__unbekannt__')?(side==='guest'?'Gast':'Heim'):p.player;
      return `<div class="ev-item"><span class="ev-nr">${i+1}.</span> ${escH(nm)} ${p.scored?'✅':'❌'}</div>`;
    }).join('');
    const pensHtml=(r.pen_shots||[]).length
      ?`<div class="mc-ev mc-ev-pen"><div class="ev-col ev-home">${penCol('home')}</div><div class="ev-mid">🥅</div><div class="ev-col ev-guest">${penCol('guest')}</div></div>`:'';

    const card=document.createElement('div');
    card.className='mc'+(isActive(r)?' running-highlight':'');
    card.innerHTML=`
      <div class="mc-top">
        <span class="badge ${sc}">${badgeLabel}</span>
        <span class="field-badge">🏟 ${fieldLabel}</span>
        ${kickoffLabel?`<span class="kickoff-badge">${kickoffLabel}</span>`:''}
        ${timerHtml}
      </div>
      <div class="mc-body">
        <div class="t-col t-home"><div class="t-name">${homeName}</div></div>
        <div class="s-col"><div class="s-main">${r.score_home??0}<span class="s-sep">:</span>${r.score_guest??0}</div>${ps?`<div class="s-pen">i.E. ${ps.h}:${ps.g}</div>`:''}${ht?`<div class="s-ht">HZ ${ht.h}:${ht.g}</div>`:''}</div>
        <div class="t-col t-guest"><div class="t-name">${guestName}</div></div>
      </div>
      ${eventsHtml}
      ${pensHtml}`;
    wrap.appendChild(card);

    // Pausenanzeige nur zwischen nicht-laufenden Spielen (nach den running-Karten)
    if(i>=running.length && i<sorted.length-1){
      const next=sorted[i+1];
      if(!isActive(next)){
        const t1=toMin(r.kickoff), t2=toMin(next.kickoff);
        if(t1!==null&&t2!==null&&t2>t1){
          const pb=document.createElement('div'); pb.className='pause-bar';
          pb.innerHTML=`<span class="pause-pill">⏱ + ${t2-t1} min</span>`;
          wrap.appendChild(pb);
        }
      }
    }

    if(isLive(r)&&r.started_at){
      liveTimers[r.id]=setInterval(()=>{
        const e2=document.getElementById(`tmr_${r.id}`);
        const ev=elapsed(r,halfSec);
        if(e2&&ev!==null)e2.textContent=fmt(ev);
      },1000);
    }
  });
  appendSquads(wrap,curMd);
}

// ═══ SPIELTAG TEILEN ═══
// Link auf die Live-Ansicht mit ?md=…; Handy: System-Teilen-Dialog, sonst Link in die Zwischenablage
async function shareMd(md,btn){
  const url=location.origin+location.pathname+'?md='+encodeURIComponent(md.id);
  const title=mdCalTitle(md);
  const text=`${fmtDate(md.date)} – ${mdLabel(md)}`;
  const flash=t=>{const o=btn.innerHTML;btn.innerHTML=t;setTimeout(()=>{btn.innerHTML=o;},2000);};
  if(navigator.share){
    try{await navigator.share({title,text,url});}catch(e){/* abgebrochen */}
    return;
  }
  try{await navigator.clipboard.writeText(url);flash('✓ Link kopiert');}
  catch(e){window.prompt('Link zum Spieltag kopieren:',url);}
}

// ═══ KADER (zuklappbar unter den Begegnungen) ═══
const RESERVED_NAMES=['eigentor','noname'];
const sqOpen={}; // Auf-/Zu-Zustand je Spieltag+Team, übersteht die Live-Aktualisierung
function sqEsc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function appendSquads(wrap,md){
  if(!md||!md.squads)return;
  Object.entries(md.squads).forEach(([tid,ids])=>{
    if(!Array.isArray(ids)||!ids.length)return;
    const team=allTeams.find(t=>t.id===tid);
    const players=allPlayers.filter(p=>ids.includes(p.id)&&!RESERVED_NAMES.includes(String(p.name).trim().toLowerCase()))
      .sort((a,b)=>a.name.localeCompare(b.name,'de',{sensitivity:'base'}));
    if(!players.length)return;
    // Tore je Spieler an diesem Spieltag (nur für dieses Team, ohne Elfmeterschießen)
    const goals={};
    curResults.forEach(r=>{
      const side=r.home_team_id===tid?'home':(r.guest_team_id===tid?'guest':null);if(!side)return;
      (r.scorers||[]).forEach(s=>{
        const n=side==='home'?(isGuestScorer(s)?null:s):(String(s).startsWith('guest:')?String(s).slice(6):null);
        if(n)goals[n]=(goals[n]||0)+1;
      });
    });
    const tName=team?team.name:'MaTo';
    const chips=players.map(p=>{
      const g=goals[p.name]||0;
      return `<span class="sq-name${g?' scored':''}">${sqEsc(p.name)}${g?` ⚽${g>1?g:''}`:''}</span>`;
    }).join('');
    const key=md.id+'|'+tid;
    const d=document.createElement('details');d.className='sq-box';if(sqOpen[key])d.open=true;
    d.innerHTML=`<summary>👥 Kader ${sqEsc(tName)}<span class="sq-n">${players.length} Spieler</span></summary><div class="sq-names">${chips}</div>`;
    d.addEventListener('toggle',()=>{sqOpen[key]=d.open;});
    wrap.appendChild(d);
  });
}

// ═══ ONLINE-ZÄHLER ═══
// Jeder Browser bekommt eine zufällige Client-ID (bleibt im localStorage erhalten),
// pingt alle 30s den Server; der zählt alle Clients der letzten 75 Sekunden.
function getCid(){
  try{
    let c=localStorage.getItem('mato_cid');
    if(!c){c='c'+Math.random().toString(36).slice(2)+Date.now().toString(36);localStorage.setItem('mato_cid',c);}
    return c;
  }catch(e){
    if(!window._matoCid)window._matoCid='c'+Math.random().toString(36).slice(2)+Date.now().toString(36);
    return window._matoCid;
  }
}
async function heartbeat(){
  try{
    const r=await fetch(`${API}?action=heartbeat`,{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({cid:getCid()})
    });
    const d=await r.json();
    if(typeof d.count==='number'){
      document.getElementById('onlineCnt').textContent=d.count;
      document.getElementById('onlineBadge').style.display='inline-flex';
    }
  }catch(e){/* Server nicht erreichbar – Badge einfach nicht aktualisieren */}
}
heartbeat();
setInterval(heartbeat,30000);

init();
</script>
</body>
</html>
